<template><ElConfigProvider namespace="kel"><section class="native-outputs"><SidebarList :sections="sections" :selectedExpression="selected?.expression" @select="item=>{expression=item.expression;trail=[];preview=''}"/><main><template v-if="selected"><header><div><h3>{{selected.label}}</h3><code>{{currentExpression}}</code></div><KsButton @click="copy">复制值</KsButton><KsButton @click="download">下载 JSON</KsButton></header><p v-if="error" role="alert">{{error}}</p><div class="output-actions"><button v-if="trail.length" @click="trail=trail.slice(0,-1);preview=''">← 上一级</button><button v-if="originTask" @click="emit('task',originTask)">产出任务 {{originTask}} →</button><button @click="emit('source')">本次执行源版本</button><a v-if="artifact" :href="artifactURL?.(artifact)" download>下载产物</a><button v-if="artifact&&previewable&&loadArtifact" :disabled="previewBusy" @click="previewArtifact">{{previewBusy?'读取中…':'安全文本预览'}}</button></div><div v-if="children.length" class="output-children"><button v-for="child in children" :key="child.key" @click="trail=[...trail,child.key];preview='' "><b>{{child.key}}</b><code>{{child.type}}</code><span>{{child.preview}} →</span></button></div><pre v-if="preview">{{preview}}</pre><small>{{current===null?'null':Array.isArray(current)?'array':typeof current}} · 来自当前 Execution 的实际输出</small><pre>{{serialized.slice(0,65536)}}</pre><p v-if="serialized.length>65536">预览已截断，下载可获取完整返回值。</p></template><KsNoData v-else title="当前执行尚无输出"/></main></section></ElConfigProvider></template>
<script setup lang="ts">
import {computed,ref} from 'vue';
import {ElConfigProvider} from 'element-plus';
import SidebarList from '../../vendor/kestra/outputs/SidebarList.vue';
import KsButton from '../../vendor/kestra/design-system/components/Basic/KsButton/KsButton.vue';
import KsNoData from '../../vendor/kestra/design-system/components/Data/KsNoData.vue';
const props=defineProps<{outputs:Record<string,unknown>;inputs?:Record<string,unknown>;taskIds?:string[];artifactURL?:(uri:string)=>string;loadArtifact?:(uri:string)=>Promise<string>}>(),expression=ref(''),error=ref(''),trail=ref<string[]>([]),preview=ref(''),previewBusy=ref(false);const emit=defineEmits(['task','source']);
const entries=(root:string,values:Record<string,unknown>)=>Object.entries(values).map(([label,value])=>({label,value,expression:root+'['+JSON.stringify(label)+']',type:value===null?'null':Array.isArray(value)?'array':typeof value,preview:JSON.stringify(value)?.slice(0,100)||String(value)}));
const inputItems=computed(()=>entries('inputs',props.inputs||{})),items=computed(()=>[...inputItems.value,...entries('outputs',props.outputs||{})]);
const sections=computed(()=>[{key:'inputs',label:'执行输入（已脱敏）',items:inputItems.value},{key:'outputs',label:'任务输出',items:items.value.filter(i=>i.expression.startsWith('outputs'))}]);
const selected=computed(()=>items.value.find(i=>i.expression===expression.value)||items.value[0]);
const current=computed(()=>trail.value.reduce((value:any,key)=>value&&typeof value==='object'?value[key]:undefined,selected.value?.value));
const currentExpression=computed(()=>(selected.value?.expression||'')+trail.value.map(key=>'['+JSON.stringify(key)+']').join(''));
const children=computed(()=>current.value&&typeof current.value==='object'?Object.entries(current.value).map(([key,value])=>({key,type:value===null?'null':Array.isArray(value)?'array':typeof value,preview:JSON.stringify(value)?.slice(0,90)||String(value)})):[]);
const originTask=computed(()=>props.taskIds?.find(id=>selected.value?.expression==='outputs['+JSON.stringify(id)+']')||'');
const artifact=computed(()=>typeof current.value==='string'&&current.value.startsWith('kestra://')?current.value:'');const previewable=computed(()=>/\.(json|txt|log|csv|yaml|yml|sh|py|xml)$/i.test(artifact.value));
const serialized=computed(()=>current.value===undefined?'':JSON.stringify(current.value,null,2)||String(current.value));
async function previewArtifact(){if(!artifact.value||!props.loadArtifact)return;previewBusy.value=true;const uri=artifact.value;try{const value=await props.loadArtifact(uri);if(uri===artifact.value)preview.value=value;error.value=''}catch(e){error.value=String(e)}finally{previewBusy.value=false}}
async function copy(){try{await navigator.clipboard.writeText(serialized.value);error.value=''}catch{error.value='浏览器未允许剪贴板写入，可下载完整 JSON'}}
function download(){const url=URL.createObjectURL(new Blob([serialized.value],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='execution-output.json';a.click();URL.revokeObjectURL(url)}
</script>
<style scoped>.native-outputs{display:grid;grid-template-columns:280px minmax(0,1fr);height:580px;background:var(--ks-bg-surface);color:var(--ks-text-primary);font-size:14px}.native-outputs>main{min-width:0;padding:20px;overflow:auto;border-left:1px solid var(--ks-border-default)}header{display:flex;align-items:center;gap:8px;margin-bottom:20px}header>div{flex:1;min-width:0}h3{margin:0;font-size:16px}code,small{color:var(--ks-text-secondary);overflow-wrap:anywhere;font-size:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.7 var(--ks-font-family-mono);padding:16px;background:var(--ks-bg-base);margin-top:12px}@media(max-width:900px){.native-outputs{grid-template-columns:200px 1fr}}</style>

<style scoped>.output-actions{display:flex;gap:16px;font-size:11px;margin:12px 0;flex-wrap:wrap;color:var(--ks-text-link)}.output-children{border-block:1px solid var(--ks-border-default);margin:12px 0;max-height:220px;overflow:auto}.output-children button{display:flex;width:100%;gap:12px;text-align:left;padding:9px;font-size:11px;border-bottom:1px solid var(--ks-border-default)}.output-children span{margin-left:auto;color:var(--ks-text-secondary);max-width:60%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.native-outputs>main header{height:auto;background:transparent;padding:0;min-height:48px}.native-outputs{font-size:12px}.native-outputs>main{padding:18px}.native-outputs h3{font-size:14px}</style>

<style scoped>.native-outputs>main{margin:0;max-width:none;width:100%;height:100%;align-self:stretch}.native-outputs>.sidebar{position:static;height:100%;min-height:0;padding:12px;display:flex;flex-direction:column;border:0;background:var(--ks-bg-base);overflow:hidden}.native-outputs main>header{width:100%}</style>
